ALTER TABLE "rides" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "ride_scoped_read" ON "rides" AS PERMISSIVE FOR SELECT TO public USING ((current_setting('rove.offer_matching',true)='true' AND NULLIF(current_setting('rove.offer_ride',true),'') IS NOT NULL AND "rides"."state" IN ('matched','en_route','arrived','in_progress','interrupted')) OR ("rides"."state"='searching' AND "rides"."search_deadline"<=NULLIF(current_setting('rove.ride_expiry_before',true),'')::timestamptz) OR NULLIF(current_setting('rove.ride_batch',true),'')::jsonb @> jsonb_build_array("rides"."id") OR "rides"."id"=NULLIF(current_setting('rove.ride_read',true),'')::uuid OR "rides"."rider_id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR "rides"."driver_id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR (current_setting('rove.actor_role',true)='rider' AND "rides"."rider_id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid) OR (current_setting('rove.actor_role',true)='driver' AND "rides"."driver_id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid) OR "rides"."rider_id"=(NULLIF(current_setting('rove.ride_create',true),'')::jsonb->>'riderId')::uuid OR "rides"."id"=NULLIF(current_setting('rove.offer_ride',true),'')::uuid OR "rides"."id"=NULLIF(current_setting('rove.quote_ride',true),'')::uuid);--> statement-breakpoint
CREATE POLICY "ride_scoped_lock" ON "rides" AS PERMISSIVE FOR UPDATE TO public USING (((current_setting('rove.offer_matching',true)='true' AND NULLIF(current_setting('rove.offer_ride',true),'') IS NOT NULL AND "rides"."state" IN ('matched','en_route','arrived','in_progress','interrupted')) OR ("rides"."state"='searching' AND "rides"."search_deadline"<=NULLIF(current_setting('rove.ride_expiry_before',true),'')::timestamptz) OR NULLIF(current_setting('rove.ride_batch',true),'')::jsonb @> jsonb_build_array("rides"."id") OR "rides"."id"=NULLIF(current_setting('rove.ride_read',true),'')::uuid OR "rides"."rider_id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR "rides"."driver_id"=NULLIF(current_setting('rove.user_read',true),'')::uuid OR (current_setting('rove.actor_role',true)='rider' AND "rides"."rider_id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid) OR (current_setting('rove.actor_role',true)='driver' AND "rides"."driver_id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid) OR "rides"."rider_id"=(NULLIF(current_setting('rove.ride_create',true),'')::jsonb->>'riderId')::uuid OR "rides"."id"=NULLIF(current_setting('rove.offer_ride',true),'')::uuid OR "rides"."id"=NULLIF(current_setting('rove.quote_ride',true),'')::uuid) AND NULLIF(current_setting('rove.ride_write',true),'')::jsonb IS NULL) WITH CHECK (false);--> statement-breakpoint
CREATE POLICY "ride_quote_create" ON "rides" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("rides"."quote_id"=(NULLIF(current_setting('rove.ride_create',true),'')::jsonb->>'quoteId')::uuid AND "rides"."rider_id"=(NULLIF(current_setting('rove.ride_create',true),'')::jsonb->>'riderId')::uuid AND "rides"."fare_cents"=(NULLIF(current_setting('rove.ride_create',true),'')::jsonb->>'fare')::integer AND "rides"."earnings_cents"=(NULLIF(current_setting('rove.ride_create',true),'')::jsonb->>'earnings')::integer AND "rides"."search_deadline"=(NULLIF(current_setting('rove.ride_create',true),'')::jsonb->>'deadline')::timestamptz AND "rides"."driver_id" IS NULL AND "rides"."state"='searching' AND "rides"."payment_state"='pending' AND "rides"."version"=1);--> statement-breakpoint
CREATE POLICY "ride_scoped_mutation" ON "rides" AS PERMISSIVE FOR UPDATE TO public USING ((NULLIF(current_setting('rove.ride_write',true),'')::jsonb->>'kind') IN ('assignment','transition','expiry','payment') AND to_jsonb(rides)=(NULLIF(current_setting('rove.ride_write',true),'')::jsonb->'before')) WITH CHECK ((NULLIF(current_setting('rove.ride_write',true),'')::jsonb->>'kind') IN ('assignment','transition','expiry','payment') AND (to_jsonb(rides)-(CASE (NULLIF(current_setting('rove.ride_write',true),'')::jsonb->>'kind') WHEN 'assignment' THEN ARRAY['driver_id','state','version','updated_at'] WHEN 'transition' THEN ARRAY['state','version','updated_at'] WHEN 'expiry' THEN ARRAY['state','version','updated_at'] WHEN 'payment' THEN ARRAY['payment_state','version','updated_at'] ELSE ARRAY[]::text[] END))=((NULLIF(current_setting('rove.ride_write',true),'')::jsonb->'before')-(CASE (NULLIF(current_setting('rove.ride_write',true),'')::jsonb->>'kind') WHEN 'assignment' THEN ARRAY['driver_id','state','version','updated_at'] WHEN 'transition' THEN ARRAY['state','version','updated_at'] WHEN 'expiry' THEN ARRAY['state','version','updated_at'] WHEN 'payment' THEN ARRAY['payment_state','version','updated_at'] ELSE ARRAY[]::text[] END)) AND "rides"."version"=((NULLIF(current_setting('rove.ride_write',true),'')::jsonb->'before')->>'version')::integer+1 AND ((NULLIF(current_setting('rove.ride_write',true),'')::jsonb->>'kind')<>'assignment' OR ("rides"."driver_id"=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND current_setting('rove.actor_role',true)='driver' AND "rides"."state"='matched' AND (NULLIF(current_setting('rove.ride_write',true),'')::jsonb->'before')->>'state'='searching' AND (NULLIF(current_setting('rove.ride_write',true),'')::jsonb->'before')->>'payment_state'='authorized')) AND ((NULLIF(current_setting('rove.ride_write',true),'')::jsonb->>'kind')<>'expiry' OR ((NULLIF(current_setting('rove.ride_write',true),'')::jsonb->'before')->>'state'='searching' AND "rides"."state" IN ('cancelled','no_driver_found'))));
--> statement-breakpoint
ALTER TABLE rides FORCE ROW LEVEL SECURITY;
